def find_next_hcf(num1: int, num2: int) -> int:
    """ This function finds the next hcf of the given two integers
    >>> find_next_hcf(30, 80)
    10
    """
    hcf = 1
    for i in range(2, min(num1, num2)+1):
        if (num1 % i == 0) and (num2 % i == 0):
            hcf = i
    return hcf

