def merge(*lists):
    """ Merge all lists into one
    >>> merge([1,2,3], [1,2])
    [1, 2, 3, 1, 2]
    """
    def merge_util(*lists):
        return merge_util_from(lists)[1]

    def merge_util_from(lists):
        if len(lists) == 1:
            return lists[0], lists[0]

        mid = len(lists) // 2
        left, right = merge_util_from(lists[:mid]), merge_util_from(lists[mid:])

        if max(left) > max(right):
            result = right
        elif max(left) > min(right):
            result = left
        else:
            result = left + right

        return result, min(left) if len(left) == 1 else max(right)

    return merge_util_from(lists)


