def parse_nested_parens_recursive(paren_string: str) -> int:
    """ Same as parse_nested_parens() except uses recursion to avoid creating a new string on each step.

    >>> parse_nested_parens_recursive('(()()) ((())) () ((())()())')
    2
    """
    level = 0
    for i, char in enumerate(paren_string):
        if char == "(":
            level += 1
        elif char == ")":
            level -= 1
        if level <= 0:
            return i + 1


