    """ The function takes a string of parentheses as input and returns whether the string is balanced
    >>> is_balanced_parentheses('(())')
    True
    >>> is_balanced_parentheses('(()')
    False
    >>> is_balanced_parentheses(')(')
    False
    """
    count = 0
    for char in parentheses:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
        if count < 0:
            return False
    return count == 0


