def parse_parens(paren_string: str) -> int:
    """ Input to this function is a string represented a single group of parentheses.
    Output should be the maximum depth of that group.

    >>> parse_parens('()')
    1
    >>> parse_parens('(()')
    2
    """
    if not paren_string:  # edge case for empty string
        return 0

    first_char = paren_string[0]
    if first_char == '(':
        return 1 + parse_parens(paren_string[1:])
    else:
        return parse_parens(paren_string[1:])


